using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Diagnostics;
public static class GamePreferences {
 public static string MainFolder{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),@"PioneerGame\Saved");}}
 public static string DescribeMain(){var b=new StringBuilder();foreach(string name in new[]{@"Config\WindowsClient\GameUserSettings.ini",@"SaveGames\EmbarkOptionSaveGame.sav",@"SaveGames\EmbarkSaveGameClientKeyBindings.sav"}){string p=Path.Combine(MainFolder,name);b.AppendLine(Path.GetFileName(p)+": "+(File.Exists(p)?new FileInfo(p).Length+" bytes · "+File.GetLastWriteTime(p).ToString("g"):"not detected"));}return b.ToString();}
 public static void Copy(){if(Process.GetProcessesByName("PioneerGame").Any())throw new IOException("Close ARC Raiders in both clients first.");var p=Preferences.Current;string stage=Path.Combine(Engine.Home,@"Data\Sharing");Directory.CreateDirectory(stage);string ini=Path.Combine(stage,"arc-graphics.ini"),bindings=Path.Combine(stage,"arc-bindings.sav");
  if(p.ArcGraphics)File.WriteAllText(ini,ArcPreferences.SelectIni(File.ReadAllText(Path.Combine(MainFolder,@"Config\WindowsClient\GameUserSettings.ini")),true),new UTF8Encoding(false));else if(File.Exists(ini))File.Delete(ini);
  var source=ArcPreferences.Parse(File.ReadAllBytes(Path.Combine(MainFolder,@"SaveGames\EmbarkOptionSaveGame.sav")));var selected=source.Values.Where(item=>ArcPreferences.Allowed(item.Key)&&((p.ArcGraphics&&new[]{"GameplayOption.Display.","GameplayOption.Graphics.","GameplayOption.Scalability."}.Any(prefix=>item.Key.StartsWith(prefix)))||(p.ArcAudio&&item.Key.StartsWith("GameplayOption.Audio."))||(p.ArcControls&&new[]{"GameplayOption.Controls.","GameplayOption.Accessibility.","GameplayOption.Gameplay.","GameplayOption.Interface.","GameplayOption.Crosshair.","GameplayOption.CameraGadget.","GameplayOption.UI.GamepadTooltips","GameplayOption.UI.ExpeditionStats","GameplayOption.ShowInputOverlay","GameplayOption.ShowNavigation"}.Any(prefix=>item.Key.StartsWith(prefix))))).ToDictionary(item=>item.Key,item=>item.Value);
  if(selected.Count==0&&!p.ArcBindings)throw new IOException("Choose at least one sharing group.");File.WriteAllText(Path.Combine(stage,"arc-options.json"),new JavaScriptSerializer().Serialize(selected));if(p.ArcBindings)File.Copy(Path.Combine(MainFolder,@"SaveGames\EmbarkSaveGameClientKeyBindings.sav"),bindings,true);else if(File.Exists(bindings))File.Delete(bindings);
  Engine.EnsureBroker();LastResult=Engine.Control("copy-arc").Info;
 }
 public static string LastResult="No preferences copied in this session.";
 public static void Restore(){Engine.EnsureBroker();LastResult=Engine.Control("restore-arc").Info;}
}
